<?php require_once 'config.php'; $title='إنشاء حساب'; $err=''; if($_SERVER['REQUEST_METHOD']==='POST') { $name=trim($_POST['full_name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$password=$_POST['password']??'';$role=$_POST['role']??'customer'; if(!in_array($role,['customer','provider'],true))$role='customer'; if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8){$err='أدخلي الاسم والبريد الصحيح وكلمة مرور من 8 أحرف على الأقل.';} else {try{$s=$pdo->prepare('INSERT INTO users(full_name,email,password_hash,phone,role) VALUES(?,?,?,?,?)');$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$phone,$role]);$id=(int)$pdo->lastInsertId();if($role==='provider'){$pdo->prepare('INSERT INTO provider_profiles(user_id,title,specialization,description,consultation_price) VALUES(?,?,?,?,?)')->execute([$id,'مقدم خدمة جديد','استشارات عامة','يرجى تعديل وصف ملفك.',0]);}$_SESSION['user']=['id'=>$id,'full_name'=>$name,'email'=>$email,'role'=>$role];flash('تم إنشاء الحساب بنجاح.');go('dashboard.php');}catch(PDOException $e){$err='هذا البريد الإلكتروني مسجل مسبقاً.';}}} require 'includes/header.php'; ?>
<div class="formbox"><h1>إنشاء حساب جديد</h1><p class="muted">اختاري نوع الحساب المناسب لك.</p><?php if($err):?><div class="error"><?=h($err)?></div><?php endif; ?><form method="post"><label>الاسم الكامل</label><input name="full_name" required maxlength="100"><label>البريد الإلكتروني</label><input type="email" name="email" required><label>رقم الهاتف (اختياري)</label><input name="phone"><label>كلمة المرور (8 أحرف على الأقل)</label><input type="password" name="password" minlength="8" required><label>نوع الحساب</label><select name="role"><option value="customer">زبون / Customer</option><option value="provider">مقدم خدمة / Service Provider</option></select><div class="btnrow"><button class="btn">إنشاء الحساب</button><a href="login.php">عندي حساب</a></div></form></div><?php require 'includes/footer.php'; ?>
